#include <iostream>
using namespace std;

class Ticket {
public:
    inline static int sold = 0;
    Ticket() { sold++; }
};

int main() {
    Ticket a, b, c;
    cout << Ticket::sold << endl;
    return 0;
}

#include <iostream>
using namespace std;

class Temperature {
public:
    static double to_fahrenheit(double c) { return c * 9 / 5 + 32; }
};

int main() {
    cout << Temperature::to_fahrenheit(100) << endl;
    return 0;
}

